<?php
session_start();
require_once 'includes/db.php';
$msg = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $name = $_POST['name'] ?? '';
    $company = $_POST['company'] ?? '';
    $country = $_POST['country'] ?? '';
    $email = $_POST['email'] ?? '';
    $phone = $_POST['phone'] ?? '';
    $product = $_POST['product'] ?? '';
    $quantity = $_POST['quantity'] ?? '';
    $packaging = $_POST['packaging'] ?? '';
    $message = $_POST['message'] ?? '';
    
    // Server-side validation
    if (!empty($name) && !empty($email)) {
        $stmt = $conn->prepare("INSERT INTO inquiries (name, company, country, email, phone, product, quantity, packaging, message, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'new')");
        if ($stmt) {
            $stmt->bind_param("sssssssss", $name, $company, $country, $email, $phone, $product, $quantity, $packaging, $message);
            if ($stmt->execute()) {
                $msg = "<p style='color:green; padding:10px; background:#e8f5e9; border-radius:5px;'>Your inquiry has been sent successfully!</p>";
            } else {
                $msg = "<p style='color:red; padding:10px; background:#fbe9e7; border-radius:5px;'>Error sending inquiry. Please try again.</p>";
            }
        }
    } else {
        $msg = "<p style='color:red;'>Please fill required fields.</p>";
    }
}
